let message = "";

const getStart = (event) => {
  const dateTime = event.json.start?.dateTime;
  if (!dateTime) return Infinity;
  return new Date(dateTime).getTime();
};

const formatTime = (date) => {
  return date.toLocaleTimeString("id-ID", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZone: "Asia/Jakarta",
  });
};

const formatRange = (start, end) => {
  const startTime = formatTime(start);
  if (!end) return `${startTime} WIB`;
  const endTime = formatTime(end);
  return `${startTime}–${endTime} WIB`;
};

const now = new Date();
const getEventStatus = (start, end) => {
  if (now >= start && now <= end) return "now";
  if (now > end) return "done";
  return "upcoming";
};

const header = "🗓️ *JADWAL HARI INI*";

if (events.length === 0) {
  return [{ json: { message: `${header}\n\nTidak ada jadwal hari ini / Kosong... Santai dulu! 😴` } }];
}

events.sort((a, b) => getStart(a) - getStart(b));

message = `${header}\n`;
let nextAssigned = false;
const lines = [];

events.forEach((event) => {
  const data = event.json;
  const title = data.summary || "Tanpa judul";

  if (data.start?.date) {
    lines.push(`• *${title}*\n  Seharian`);
    return;
  }
  if (!data.start?.dateTime) return;

  const start = new Date(data.start.dateTime);
  const end = data.end?.dateTime ? new Date(data.end.dateTime) : new Date(start.getTime() + 60 * 60 * 1000);
  const eventStatus = getEventStatus(start, end);
  const time = formatRange(start, end);

  let prefix = "•";
  let statusText = "";
  if (eventStatus === "now") { prefix = "🔥"; statusText = " *NOW*"; }
  else if (eventStatus === "done") { prefix = "✓"; }
  else if (eventStatus === "upcoming" && !nextAssigned) { prefix = "👉"; statusText = " *NEXT*"; nextAssigned = true; }

  let formattedTitle = eventStatus === "done" ? `~*${title}*~` : `*${title}*`;
  lines.push(`${prefix} ${formattedTitle}${statusText}\n  ${time}`);
});

if (lines.length === 0) {
  message += "\n\nTidak ada jadwal hari ini / Kosong... Santai dulu! 😴";
} else {
  message += "\n" + lines.join("\n\n");
}

return [{ json: { message } }];

